div.script:
document.addEventListener('DOMContentLoaded', function () {
    const container = document.getElementById('skills_container');
    const addBtn = document.getElementById('add_skill_row');
    const form = document.getElementById('hr_recruitment_form');

    function validateSkills() {
        const rows = container.querySelectorAll('.skill-row');
        let valid = true;

        container.querySelectorAll('.skill-error').forEach(el => el.remove());
        container.querySelectorAll('select').forEach(el => el.style.borderColor = '');

        rows.forEach(function (row, index) {
            const skillType = row.querySelector('.skill-type');
            const skillSel = row.querySelector('.skill');
            const levelSel = row.querySelector('.level');

            if (!skillType.value) {
                skillType.style.borderColor = 'red';
                skillType.style.outline = '1px solid red';
                valid = false;
            }
            if (!skillSel.value) {
                skillSel.style.borderColor = 'red';
                skillSel.style.outline = '1px solid red';
                valid = false;
            }
            if (!levelSel.value) {
                levelSel.style.borderColor = 'red';
                levelSel.style.outline = '1px solid red';
                valid = false;
            }
        });

        return valid;
    }

    const applyBtn = document.getElementById('apply-btn');

    applyBtn.addEventListener('click', function (e) {
        const skillsValid = validateSkills();
        if (!skillsValid) {
            e.preventDefault();
            e.stopImmediatePropagation();

            const warning = document.getElementById('warning-message');
            if (warning) {
                warning.textContent = 'Please complete all Skill Type, Skill, and Level fields.';
                warning.classList.remove('d-none');
            }

            container.scrollIntoView({ behavior: 'smooth', block: 'center' });
        } else {
            const warning = document.getElementById('warning-message');
            if (warning) warning.classList.add('d-none');

            container.querySelectorAll('select').forEach(el => {
                el.style.borderColor = '';
                el.style.outline = '';
            });
        }
    }, true);

    if (form) {
        form.addEventListener('submit', function (e) {
            if (!validateSkills()) {
                e.preventDefault();
                e.stopImmediatePropagation();
                const warning = document.getElementById('warning-message');
                if (warning) {
                    warning.textContent = 'Please complete all Skill Type, Skill, and Level fields.';
                    warning.classList.remove('d-none');
                }
                container.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }, true);
    }

    addBtn.addEventListener('click', function () {
        const firstRow = container.querySelector('.skill-row');
        const newRow = firstRow.cloneNode(true);

        newRow.querySelectorAll('select').forEach(el => {
            el.innerHTML = 'Select...';
            el.disabled = true;
            el.style.borderColor = '';
            el.style.outline = '';
        });

        newRow.querySelector('.skill-type').innerHTML = firstRow.querySelector('.skill-type').innerHTML;
        newRow.querySelector('.skill-type').disabled = false;

        container.appendChild(newRow);
    });

    container.addEventListener('click', function (e) {
        if (e.target.classList.contains('remove-row')) {
            if (container.querySelectorAll('.skill-row').length > 1) {
                e.target.closest('.skill-row').remove();
            }
        }
    });

    container.addEventListener('change', function (e) {
        const row = e.target.closest('.skill-row');

        e.target.style.borderColor = '';
        e.target.style.outline = '';

        if (e.target.classList.contains('skill-type')) {
            const skillTypeId = e.target.value;
            const skillSelect = row.querySelector('.skill');
            const levelSelect = row.querySelector('.level');

            skillSelect.innerHTML = 'Loading...';
            levelSelect.innerHTML = 'Select Skill First';
            levelSelect.disabled = true;

            fetch('/get/skills', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    jsonrpc: "2.0",
                    method: "call",
                    params: { skill_type_id: skillTypeId },
                    id: Date.now()
                })
            })
            .then(res => res.json())
            .then(data => {
                skillSelect.innerHTML = 'Select Skill';
                data.result.forEach(skill => {
                    skillSelect.innerHTML += `${skill.name}`;
                });
                skillSelect.disabled = false;
            });
        }

        if (e.target.classList.contains('skill')) {
            const skillId = e.target.value;
            const levelSelect = row.querySelector('.level');

            levelSelect.innerHTML = 'Loading...';

            fetch('/get/skill/levels', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    jsonrpc: "2.0",
                    method: "call",
                    params: { skill_id: skillId },
                    id: Date.now()
                })
            })
            .then(res => res.json())
            .then(data => {
                levelSelect.innerHTML = 'Select Level';
                data.result.forEach(level => {
                    levelSelect.innerHTML += `${level.name}`;
                });
                levelSelect.disabled = false;
            });
        }
    });
});
